import  {Snackbar}  from '@mui/material';
import { PDFViewer } from '@react-pdf/renderer';
import { useFormContext } from '../../../../Contexts/FormExerciseContext';
import getFormName from '../../../../utils/getFormName';
import StatusModal from '../../../../Component/StatusModal';
import { useLanguage } from '../../../../Contexts/LanguageContext';
import ExerciseTestView from '../../../../Services/ToolsPDF/ExerciseTestView';

const Confirmation = ({ onPrev }) => {
  const { t } = useLanguage();
  const { 
    formData,
    handleSubmit,
    levels,
    filteredMatriels,
    filteredUnits,
    errorAdding,
    snackbarOpen,
    setSnackbarOpen,
    snackbarMessage,
    isErrorOpen,
    setIsErrorOpen,
   exerciseData } = useFormContext();
  const levelName = getFormName(formData.level,levels);
  const materialName = getFormName(formData.material,filteredMatriels);
  const unitName = getFormName(formData.unit,filteredUnits);
  return (
    <div>
      <h2 className="text-2xl font-bold mb-4">{t("Confirmation")}</h2>
      <p className="mb-4">{t("confirmationMsg")}</p>
      <ul className="list-disc list-inside mb-4">
        <li>{t("Level")}: {levelName}</li>
        <li>{t("Trimester")}: {formData.Trimester}</li>
        <li>{t("Matriel")}: {materialName}</li>
        <li>{t("Unit")}: {unitName}</li>
        <li>{t("Difficulty")}: {formData.difficulty}</li>
      </ul>
      <div className="p-4">
      <h2 className="text-xl font-bold mb-4">{t("The_Exercise")}</h2> 
      <PDFViewer 
       width='100%' 
       height={'400'} 
       showToolbar={false}>
        <ExerciseTestView exercise={exerciseData} />
      </PDFViewer>
    </div>
      <div className="flex justify-between">
        <button
          onClick={onPrev}
          className="bg-gray-500 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
        >
          {t("Previous")}
        </button>
        <button
          onClick={handleSubmit}
          className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
        >
          {t("Submit")}
        </button>
      </div>
      { isErrorOpen && (
            <StatusModal
              type="error"
              title="Error Occurredr"
              message={errorAdding}
              isOpen={isErrorOpen}
              onClose={() => setIsErrorOpen(false)}
            />
             )}
      <Snackbar
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={() => setSnackbarOpen(false)}
        message={snackbarMessage}
      />
    </div>
  );
};

export default Confirmation;