import { useState } from 'react';
import  {Snackbar}  from '@mui/material';
import { useLanguage } from '../../Contexts/LanguageContext';
import api from '../../Services/api'
const Security = () => {
  const { t } = useLanguage();
  const [ currentPassword, setCurrentPassword] = useState('');
  const [ newPassword, setNewPassword] = useState('');
  const [ confirmationPassword, setConfirmationPassword] = useState('');

  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');
 
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      await api.post(`/api/user/change-password`, { currentPassword, newPassword, confirmationPassword });
      setSnackbarOpen(true);
      setSnackbarMessage('The infomation has update successfully');
    } catch (err) {
        setError(
            err.response?.data?.message || 'Something went wrong. Please try again.'
          );
          console.log(err)
    } finally {
      setIsLoading(false);
    }
  };
 

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-2">{t("Security")}</h2>
        <form onSubmit={handleSubmit} className="space-y-4 flex flex-col">
          <div>
            <label htmlFor="CurrentPassword" className="block text-sm font-medium">
              {t("CurrentPassword")}
            </label>
            <input
              id="CurrentPassword"
              type="password"
              placeholder=" Your Current Password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="newPassword" className="block text-sm font-medium">
              {t("New_password")}
            </label>
            <input
              id="newPassword"
              type="password"
              placeholder=" Your New password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          <div>
            <label htmlFor="ConfirmationPassword" className="block text-sm font-medium">
              {t("Confiramtion_password")}
            </label>
            <input
              id="ConfirmationPassword"
              type="password"
              value={confirmationPassword}
              onChange={(e) => setConfirmationPassword(e.target.value)}
              required
              className="mt-1 mx-3 w-full input-primary"
            />
          </div>
          {(error) && (
            <div className="text-red-600 text-sm flex items-center gap-2">
              <span>{error}</span>
            </div>
          )}
          <button
            type="submit"
            disabled={isLoading}
            className={`w-3/4 mx-auto btn-primary`}
          >
            {isLoading ? t("loadingMsg") : t("save")}
          </button>
        </form>
      </div>
      <Snackbar
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'center',
        }}
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={() => setSnackbarOpen(false)}
        message={snackbarMessage}
      />
    </div>
  );
};

export default Security;